PEAK, BW = 1979e12 / 2, 3.35e12
def ai(kind, n, b=2):                      # b = 원소당 바이트(bf16=2)
    if kind == "dot":    return (2*n - 1) / (b*n + b*n + b)
    if kind == "matvec": return n*(2*n - 1) / (b*n + b*n*n + b*n)
    if kind == "matmul": return n*n*(2*n - 1) / (3 * b*n*n)
print("n     dot   matvec   matmul | 피크 대비 도달 비율")
for n in (64, 256, 1024, 4096):
    row = [ai(k, n) for k in ("dot", "matvec", "matmul")]
    roof = [min(PEAK, a * BW) / PEAK for a in row]   # 루프라인
    print(n, " ".join(f"{a:8.2f}" for a in row), " |",
          " ".join(f"{r:6.1%}" for r in roof))
print("fp32 로 바꾸면 n=1024 matmul AI =", round(ai("matmul", 1024, 4), 1))
